const P={};
P.home=()=>`<div class="hero2"><div class="orbs" aria-hidden="true">${IC.map((e,i)=>`<span style="left:${(i*37+5)%92}%;top:${(i*53+8)%80}%;font-size:${26+i%3*14}px;animation-delay:-${i*1.3}s">${e}</span>`).join("")}</div>
<div class="w2"><p class="greet">ආයුබෝවන් · வணக்கம் · WELCOME</p><h1 class="wm">${wm("cHooSe cHoIce")}</h1><p class="tag2">${t("tag")}</p><p class="sub">${t("sub")}</p>
<form class="finder" id="ff"><label for="fq">${t("finder")}</label><div class="row"><input id="fq" placeholder='e.g. "water is leaking" or "AC not cooling"' autocomplete="off"><button class="btn gold">${t("match")}</button><button type="button" class="btn s ghost" id="mic" aria-label="Voice search">🎤</button></div>
<div class="chips">${["Water leaking","AC not cooling","Wedding photos","Wi-Fi not working","Need a mover"].map(x=>`<button type="button" class="chip" data-q="${x}">${x}</button>`).join("")}</div><div id="fr"></div></form>
<div class="row"><a class="btn" href="services.html">${t("explore")}</a> <a class="btn gold" href="providers.html?emergency=1">🚨 ${t("emerg")}</a> <a class="btn s ghost" href="dashboard.html">${t("become")}</a></div></div></div>
<div class="stats"><div><b data-n="${SVC.length}">0</b><span>services listed</span></div><div><b data-n="${CATS.length}">0</b><span>categories</span></div><div><b data-n="${ALLD.length}">0</b><span>districts covered</span></div><div><b>Rs. 0</b><span>to join at launch</span></div></div>
${season()}<div class="mq" aria-hidden="true"><div class="mqi">${[0,1].map(()=>SVC.filter((_,i)=>i%3==0).slice(0,70).map(s=>`<span>${IC[+s.cat.slice(1)-1]} ${esc(s.en)}</span>`).join("")).join("")}</div></div>
<section><h2>Pick your category</h2><div class="g" style="grid-template-columns:repeat(auto-fill,minmax(170px,1fr))">${CATS.map((c,i)=>`<a class="tile" href="services.html" data-cat="${c.id}"><span class="ic">${IC[i]}</span><h3>${esc(c.name)}</h3><span class="m">${SVC.filter(s=>s.cat==c.id).length} services</span></a>`).join("")}</div></section>
<section><h2>3 steps to the right person</h2><div class="g steps">${[["Describe it","Search or tell us the problem in your own words."],["Compare","See rating, experience, area and live availability."],["Connect","Open the profile and reach out. Free at launch."]].map(x=>`<div class="c step"><h3>${x[0]}</h3><span class="m">${x[1]}</span></div>`).join("")}</div></section>
<section><h2>Featured providers <span class="demo">Demo data</span></h2><div class="g">${PROV.slice(0,6).map(pcard).join("")}</div></section>
<section><h2>Browse by need</h2><div class="row">${["Home repairs","Construction / renovation","Cleaning","Appliance repair","Transport","Events","Business services","Agriculture"].map(x=>`<a class="btn s" href="services.html">${x}</a>`).join("")}</div></section>
<section><h2>Browse by province</h2><div class="g">${Object.entries(DISTRICTS).map(([p,d])=>`<div class="c"><h3>${p}</h3><span class="m">${d.map(x=>`<a href="providers.html" data-d="${x}">${x}</a>`).join(" · ")}</span></div>`).join("")}</div></section>
<section><h2>Nearby shops <span class="demo">Sample records</span></h2><div class="g">${SHOPS.slice(0,4).map(shopCard).join("")}</div><p><a href="shops.html">All shops →</a></p></section>
<section><h2>Trust and safety</h2><div class="g">${[["Verification","Badges appear only after genuine verification."],["Reviews","Reviews can be reported and moderated."],["Privacy","NIC numbers and documents are never public."],["Availability","Providers must reconfirm every 24 hours."]].map(x=>`<div class="c"><h3>${x[0]}</h3><span class="m">${x[1]}</span></div>`).join("")}</div></section>
<section class="c" style="text-align:center"><h2>Ready to get started?</h2><a class="btn" href="services.html">Find a service</a> <a class="btn s" href="contact.html">Join as a provider</a><p class="m">Free for all customers and providers.</p></section>`;
P.categories=()=>`<section><h1>Categories</h1><p class="m">${CATS.length} parent categories · ${SUBS.length} subcategories · ${SVC.length} services</p>${CATS.map(c=>`<div class="c" style="margin-bottom:12px"><h3>${esc(c.name)}</h3>${SUBS.filter(s=>s.cat==c.id).map(s=>`<p class="m"><b>${esc(s.name)}:</b> ${SVC.filter(v=>v.sub==s.id).map(v=>esc(v.en)).join(", ")}</p>`).join("")}</div>`).join("")}</section>`;
let SF={q:"",cat:"",d:"",pg:0};
P.services=()=>`<section><h1>Explore Services</h1><div class="sb" style="max-width:none"><input id="sq" placeholder="Search services or keywords" value="${esc(SF.q)}"><select id="sc">${cOpts(SF.cat)}</select><select id="sd">${dOpts(SF.d)}</select><button class="btn s" id="rs">Reset</button></div><p class="m" id="sn"></p><div class="g" id="sl"></div><div class="row" style="margin-top:14px"><button class="btn s" id="pv">Previous</button><button class="btn s" id="nx">Next</button></div></section>`;
function runSvc(){const q=SF.q.toLowerCase().trim();const r=SVC.filter(s=>s.active&&(!SF.cat||s.cat==SF.cat)&&(!q||q.split(/\s+/).every(w=>s.kw.includes(w))));const per=24,max=Math.max(0,Math.ceil(r.length/per)-1);SF.pg=Math.min(SF.pg,max);
$("#sn").textContent=r.length+" matching services (of "+SVC.length+")";$("#sl").innerHTML=r.length?r.slice(SF.pg*per,SF.pg*per+per).map(s=>`<div class="c"><h3>${esc(s.en)}</h3><span class="m">${esc(catName(s.cat))} › ${esc(subName(s.sub))}</span><p><a href="providers.html" data-svc="${esc(s.en)}" data-d="${SF.d}">Find providers →</a></p></div>`).join(""):`<div class="c">No services match. Try different words or reset filters.</div>`;$("#pv").disabled=SF.pg==0;$("#nx").disabled=SF.pg>=max}
let PF={q:"",cat:"",d:"",av:false,ver:false,minr:0,sort:"rel"};
P.providers=()=>`<section><h1>Find Professionals <span class="demo">Demo data</span></h1><div class="sb" style="max-width:none"><input id="pq" placeholder="Service or name" value="${esc(PF.q)}"><select id="pc">${cOpts(PF.cat)}</select><select id="pd">${dOpts(PF.d)}</select>
<select id="pr"><option value="0">Any rating</option><option value="4">4★+</option><option value="4.5">4.5★+</option></select><select id="ps"><option value="rel">Relevance</option><option value="rating">Rating</option><option value="exp">Experience</option></select>
<label><input type="checkbox" id="pa"> Available now</label><label><input type="checkbox" id="pe"> 🚨 Emergency mode</label><label><input type="checkbox" id="pv2"> Verified</label><button class="btn s" id="prs">Reset</button></div><div class="g" id="pl"></div><h2 style="margin-top:24px">Map view</h2><p class="m">Open a district on Google Maps:</p><div class="chips">${ALLD.map(d=>`<a class="btn s" style="padding:5px 10px;font-size:13px" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(d+" District Sri Lanka")}">${d}</a>`).join("")}</div></section>`;
function runProv(){let r=PROV.filter(p=>(!PF.cat||p.cat==PF.cat)&&(!PF.d||p.d==PF.d)&&(!PF.q||(p.svc+" "+p.name).toLowerCase().includes(PF.q.toLowerCase()))&&(!PF.av||(p.st=="Available"&&p.hrs<24))&&(!PF.em||(URG.includes(p.cat)&&p.st=="Available"&&p.hrs<24))&&(!PF.ver||p.ver)&&p.r>=PF.minr);
if(PF.sort=="rating")r.sort((a,b)=>b.r-a.r);if(PF.sort=="exp")r.sort((a,b)=>b.exp-a.exp);$("#pl").innerHTML=r.length?r.map(pcard).join(""):`<div class="c">No providers match yet. Reset filters or try another district.</div>`}
P.provider=id=>{const p=PROV.find(x=>x.id==id);if(!p)return P.nf();const ok=canContact(p);return `<section><a href="providers.html">← Back</a><div class="c" style="margin-top:10px"><span class="demo">Sample profile</span><h1>${esc(p.name)}</h1><p class="m">${esc(p.svc)} · ${p.d} district · ${p.exp} years experience</p><p>${avail(p)} ${p.ver?'<span class="tag">✔ Verified (demo)</span>':'<span class="tag t-u">Not verified</span>'}</p>
<p>${stars(p.r)} ${p.r} from ${p.rv} sample reviews</p><button class="btn" id="ct" ${ok?"":"disabled"}>${ok?"Show contact (free at launch)":"Contact locked – availability needs reconfirmation"}</button><p id="cn" class="m"></p><div class="row"><a class="btn s" href="request.html?ids=${p.id}">Request a quote</a> <a class="btn s" href="providers.html">Back to results</a></div>
${trustTable(p)}<h2>Reviews</h2>${REV.map(v=>`<div class="c" style="margin-bottom:8px"><b>${v[0]}</b> ${stars(v[1])}<br>${v[2]}<br><a href="provider.html?id=${p.id}" class="m" onclick="alert('Demo: review report submitted for moderation');return false">Report review</a></div>`).join("")}</div></section>`};
function shopCard(s){return `<div class="c"><span class="demo">Sample</span><h3>${s.n}</h3><p class="m">${s.t} · ${s.town}, ${s.d}<br>Related: ${s.rel}</p><a class="btn s" target="_blank" rel="noopener" href="${maps(s)}">Google Maps directions</a></div>`}
P.shops=()=>`<section><h1>Nearby Shops <span class="demo">Sample records</span></h1><p class="m">No real shops or numbers are shown. Shop owners will be able to submit business details for review.</p><div class="g">${SHOPS.map(shopCard).join("")}</div></section>`;
P.how=()=>`<section><h1>How It Works</h1><div class="g"><div class="c"><h3>Customers</h3><ol><li>Search a service and district.</li><li>Compare ratings, experience and availability.</li><li>View a profile and contact a provider.</li></ol></div><div class="c"><h3>Providers</h3><ol><li>Create a free profile.</li><li>List services and areas.</li><li>Reconfirm availability every 24 hours.</li></ol></div></div></section>`;
P.about=()=>`<section><h1>About (draft)</h1><p>cHooSe cHoIce is a demonstration prototype of a Sri Lankan service marketplace. It does not claim to be an existing or leading platform. Free at launch; optional paid features are future ideas only.</p></section>`;
P.privacy=()=>`<section><h1>Privacy Policy (draft)</h1><p>Draft only – not legally reviewed. Production use needs review against applicable Sri Lankan law. Customers will be able to request their data and account deletion. Identity documents will never be public.</p></section>`;
P.terms=()=>`<section><h1>Terms of Service (draft)</h1><p>Draft only – not legally reviewed. Any future paid feature must show price, terms and refund rules before payment.</p></section>`;
P.help=()=>`<section><h1>Help, FAQs and Reports</h1><div class="c"><h3>Why is a provider's contact locked?</h3><p class="m">Availability confirmations expire after 24 hours.</p></div><div class="c"><h3>Report a problem</h3><p class="m">Demo form – nothing is sent.</p></div></section>`;
const form=(t)=>`<section style="max-width:420px"><h1>${t}</h1><p class="demo">Demo only – not secure authentication. Nothing is stored.</p><form id="af" novalidate>${t=="Sign Up"?'<div class="f"><label for="nm">Full name</label><input id="nm"><span class="err"></span></div>':""}<div class="f"><label for="em">Email</label><input id="em" type="email"><span class="err"></span></div>${t=="Sign Up"?'<div class="f"><label for="ph">Phone (07X XXX XXXX)</label><input id="ph"><span class="err"></span></div>':""}<div class="f"><label for="pw">Password</label><input id="pw" type="password"><span class="err"></span></div><button class="btn">${t}</button> <p id="ok" class="m"></p></form></section>`;
P.login=()=>form("Login");P.signup=()=>form("Sign Up");
let DT="Customer";
P.dashboard=()=>`<section><h1>Dashboard <span class="demo">Demo</span></h1><div class="tabs">${["Customer","Provider"].map(t=>`<button class="${t==DT?"on":""}" data-t="${t}">${t}</button>`).join("")}</div>${DT=="Customer"?`<div class="g">${["Saved providers","Hire again","Quotes received","Recent searches","Service requests","Contact-unlock history","Payment history (none – free launch)","Privacy settings","Request account deletion"].map(x=>`<div class="c"><h3>${x}</h3><span class="m">Empty in demo</span></div>`).join("")}</div>`:
`<div class="c" style="margin-bottom:12px"><h3>Availability</h3><p class="m">Set your real capacity. Requests never change it automatically.</p><div class="row"><select id="ast"><option>Available</option><option>Busy</option><option>Unavailable</option></select><button class="btn" id="arc">Reconfirm now</button></div><p id="am" class="m"></p></div><div class="g">${["Profile editor","Skills and services","Languages spoken","Working hours","Service areas","Portfolio","Reviews","Verification status","Request notifications"].map(x=>`<div class="c"><h3>${x}</h3><span class="m">Demo placeholder</span></div>`).join("")}<div class="c"><h3>Subscription</h3><button class="btn" disabled>Upgrade (not available)</button></div></div>`}</section>`;
P.admin=()=>`<section><h1>Admin <span class="demo">Concept · sample data</span></h1><p class="m">Real role permissions must be enforced server-side.</p><div class="g"><div class="c"><h3>${SVC.length}</h3><span class="m">Services in catalogue</span></div><div class="c"><h3>${CATS.length} / ${SUBS.length}</h3><span class="m">Categories / subcategories</span></div><div class="c"><h3>${PROV.length}</h3><span class="m">Sample providers</span></div></div><div class="c sc" style="margin-top:14px"><h3>Verification queue (sample)</h3><table><tr><th>Provider</th><th>Type</th><th>Status</th></tr><tr><td>Sample Plumber B</td><td>Identity</td><td>Pending</td></tr><tr><td>Sample Carpenter F</td><td>Phone</td><td>Pending</td></tr></table></div><p class="m">Also planned: category management, reported listings, review moderation, complaints, shop listings, analytics, settings.</p></section>`;
P.nf=()=>`<section><h1>Page not found</h1><a href="index.html">Home</a></section>`;
try{const t=JSON.parse(sessionStorage.getItem("st")||"null");if(t){SF=t.SF;PF=t.PF}}catch(e){}addEventListener("pagehide",()=>{try{sessionStorage.setItem("st",JSON.stringify({SF,PF}))}catch(e){}});
const doc=(h,b)=>()=>`<section style="max-width:760px"><h1>${h}</h1><p class="demo">Draft – not legally reviewed. Review Sri Lankan law before launch.</p>${b}</section>`;
const df=(h,fs,btn)=>()=>`<section style="max-width:520px"><h1>${h}</h1><p class="demo">Demo only – nothing is sent.</p><form class="dform" novalidate>${fs.map(f=>`<div class="f"><label for="${f[0]}">${f[1]}</label>${f[2]=="ta"?`<textarea id="${f[0]}" rows="4"></textarea>`:`<input id="${f[0]}" type="${f[2]}">`}<span class="err"></span></div>`).join("")}<button class="btn">${btn}</button><p class="m ok"></p></form></section>`;
P.community=doc("Community Guidelines","<ul><li>Be respectful and honest in requests, replies and reviews.</li><li>No harassment, hate speech, fraud or fake reviews.</li><li>Never share other people's private details.</li><li>Report problems using Report a Problem.</li></ul>");
P.pguide=doc("Provider Guidelines","<ul><li>Describe your skills and experience truthfully.</li><li>Set availability to match your real capacity and reconfirm every 24 hours.</li><li>Only show a verification badge after genuine verification.</li><li>Respond to requests politely and quote clearly.</li></ul>");
P.complaints=doc("Complaints and Disputes","<p>Use Report a Problem to describe the issue. In the real service, complaints would be logged, reviewed by moderators, and both sides given a chance to respond. This page is a placeholder.</p>");
P.deletion=doc("Account Deletion and Personal Data","<p>In the real service you will be able to request a copy of your personal data and ask for your account to be deleted. Reviews that are legitimate may stay in anonymised form. This page is a placeholder – nothing is stored in this demo.</p>");
P.contact=df("Contact",[["cn1","Your name","text"],["ce","Email","email"],["cm","Message","ta"]],"Send");
P.report=df("Report a Problem",[["re","Your email","email"],["rm","What went wrong?","ta"]],"Submit report");
P.forgot=df("Forgot password",[["fe","Email","email"]],"Send reset link");
P.compare=()=>{const r=CMP.map(i=>PROV.find(p=>p.id==i)).filter(Boolean);return `<section><h1>${t("compare")} <span class="demo">Sample</span></h1>`+(r.length?`<div class="sc"><table><tr><th></th>${r.map(p=>`<th>${esc(p.name)}</th>`).join("")}</tr>`+[["Service",p=>esc(p.svc)],["District",p=>p.d],["Rating",p=>p.r+" ("+p.rv+" sample reviews)"],["Experience",p=>p.exp+" yrs"],["Availability",p=>avail(p)],["Verified",p=>p.ver?"Yes (demo)":"No"],["Trust score",p=>trust(p).total+"/100"],["",p=>`<a href="provider.html?id=${p.id}">Profile</a>`]].map(x=>`<tr><th>${x[0]}</th>${r.map(p=>`<td>${x[1](p)}</td>`).join("")}</tr>`).join("")+"</table></div>":`<div class="c">Nothing to compare yet. Tick Compare on up to 3 providers in <a href="providers.html">Find Professionals</a>.</div>`)+"</section>"};
P.request=()=>{const ids=(new URLSearchParams(location.search).get("ids")||"").split(",").map(Number);return `<section style="max-width:760px"><h1>Request quotes <span class="demo">Demo</span></h1><p class="m">Pick up to 3 providers and send one request. Replies are simulated.</p><form id="rq" class="dform" novalidate><div class="f"><label for="rd">Describe the job</label><textarea id="rd" rows="3"></textarea><span class="err"></span></div><div class="f"><label>Providers (max 3)</label>${PROV.map(p=>`<label><input type="checkbox" name="rp" value="${p.id}" ${ids.includes(p.id)?"checked":""}> ${esc(p.name)} – ${esc(p.svc)}</label>`).join("")}<span class="err"></span></div><button class="btn">Send request</button></form><div id="rr"></div></section>`};
P.nf=()=>`<section style="text-align:center"><h1>404 – page not found</h1><p class="m">That page does not exist.</p><a class="btn" href="index.html">Go home</a></section>`;
P.offline=()=>`<section style="text-align:center"><h1>You are offline</h1><p class="m">Reconnect to continue. Pages you visited before may still open.</p><a class="btn" href="index.html">Try home</a></section>`;
// ---- router ----
function route(){let k=document.body.dataset.page,id=new URLSearchParams(location.search).get("id");if(!P[k])k="nf";app.innerHTML=P[k](id);$("#menu").classList.remove("o");$("#mb").setAttribute("aria-expanded","false");scrollTo(0,0);applyI();
document.querySelectorAll("nav a.l").forEach(a=>a.classList.toggle("on",a.getAttribute("href")==(location.pathname.split("/").pop()||"index.html")));
if(k=="services"){runSvc();const b=()=>{SF.q=$("#sq").value;SF.cat=$("#sc").value;SF.d=$("#sd").value;SF.pg=0;runSvc()};$("#sq").oninput=b;$("#sc").onchange=b;$("#sd").onchange=b;$("#rs").onclick=()=>{SF={q:"",cat:"",d:"",pg:0};route()};$("#pv").onclick=()=>{SF.pg--;runSvc()};$("#nx").onclick=()=>{SF.pg++;runSvc()}}
if(k=="providers"){if(new URLSearchParams(location.search).get("emergency"))PF.em=true;runProv();$("#pr").value=PF.minr;$("#ps").value=PF.sort;$("#pa").checked=PF.av;$("#pe").checked=!!PF.em;$("#pv2").checked=PF.ver;const b=()=>{PF={q:$("#pq").value,cat:$("#pc").value,d:$("#pd").value,av:$("#pa").checked,em:$("#pe").checked,ver:$("#pv2").checked,minr:+$("#pr").value,sort:$("#ps").value};runProv()};["pq","pc","pd","pr","ps","pa","pe","pv2"].forEach(i=>$("#"+i).oninput=b);$("#prs").onclick=()=>{PF={q:"",cat:"",d:"",av:false,ver:false,minr:0,sort:"rel"};route()}}
if(k=="home"){const run=q=>{const r=match(q);$("#fr").innerHTML=r.length?'<p class="m2">Best matches – tap one to see providers:</p><div class="chips">'+r.map(s=>`<a class="chip hit" href="providers.html" data-svc="${esc(s.en)}">${IC[+s.cat.slice(1)-1]} ${esc(s.en)}</a>`).join("")+"</div>":'<p class="m2">No match yet – try other words or <a href="services.html">browse all services</a>.</p>';document.querySelectorAll(".hit").forEach(a=>a.onclick=()=>{PF.q=a.dataset.svc})};
$("#ff").onsubmit=e=>{e.preventDefault();run($("#fq").value)};document.querySelectorAll(".chip[data-q]").forEach(b=>b.onclick=()=>{$("#fq").value=b.dataset.q;run(b.dataset.q)});
document.querySelectorAll("[data-n]").forEach(el=>{const t=+el.dataset.n,st=Math.max(1,Math.ceil(t/40));let c=0;const iv=setInterval(()=>{c=Math.min(t,c+st);el.textContent=c;if(c>=t)clearInterval(iv)},25)});$("#mic").onclick=()=>{const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){alert("Voice search is not supported in this browser.");return}const r=new R();r.lang={en:"en-LK",si:"si-LK",ta:"ta-LK"}[LANG];r.onresult=e=>{$("#fq").value=e.results[0][0].transcript;run($("#fq").value)};r.start()}}
if(k=="provider"&&$("#ct"))$("#ct").onclick=()=>{$("#cn").innerHTML='Demo contact – placeholder only, no real numbers: <button class="btn s" disabled>📞 Call</button> <button class="btn s" disabled>💬 WhatsApp</button> <button class="btn s" disabled>✉️ SMS</button>'};
if(k=="dashboard"){document.querySelectorAll("[data-t]").forEach(b=>b.onclick=()=>{DT=b.dataset.t;route()});if($("#arc"))$("#arc").onclick=()=>{$("#am").textContent="Reconfirmed as "+$("#ast").value+" – valid for 24 hours (demo)."}}
if(k=="login"||k=="signup")$("#af").onsubmit=e=>{e.preventDefault();let ok=true;const set=(id,bad,msg)=>{const el=$("#"+id);if(!el)return;el.nextElementSibling.textContent=bad?msg:"";if(bad)ok=false};
set("nm",!($("#nm")||{}).value?.trim(),"Enter your name");set("em",!/^\S+@\S+\.\S+$/.test($("#em").value),"Enter a valid email");set("ph",$("#ph")&&!/^(\+94|0)7\d{8}$/.test($("#ph").value.replace(/\s/g,"")),"Use format 07X XXX XXXX");set("pw",$("#pw").value.length<8,"At least 8 characters");$("#ok").textContent=ok?"Looks valid. Demo only – no account created.":""};
document.querySelectorAll("[data-cat]").forEach(a=>a.onclick=()=>{SF={q:"",cat:a.dataset.cat,d:"",pg:0}});document.querySelectorAll("[data-d]").forEach(a=>a.onclick=()=>{PF.d=a.dataset.d;if(a.dataset.svc)PF.q=a.dataset.svc});}
$("#mb").onclick=()=>{const o=$("#menu").classList.toggle("o");$("#mb").setAttribute("aria-expanded",o)};
function updCmp(){let b=$("#cb");if(!b){b=document.createElement("div");b.id="cb";document.body.appendChild(b)}b.style.display=CMP.length?"flex":"none";b.innerHTML=`<span>${CMP.length}/3 ${t("compare")}</span><a class="btn" href="compare.html">${t("compare")} →</a><button class="btn s" id="cx" type="button" aria-label="Clear">✕</button>`}
document.addEventListener("change",e=>{const c=e.target;if(!c.classList||!c.classList.contains("cmp"))return;const id=+c.dataset.id;if(c.checked){if(CMP.length>=3){c.checked=false;alert("You can compare up to 3 providers.");return}CMP.push(id)}else CMP=CMP.filter(x=>x!=id);sv();updCmp()});
document.addEventListener("click",e=>{if(e.target.id=="cx"){CMP=[];sv();document.querySelectorAll(".cmp").forEach(x=>x.checked=false);updCmp()}});
document.addEventListener("submit",e=>{const f=e.target;if(!f.classList.contains("dform"))return;e.preventDefault();let ok=true;f.querySelectorAll(".f").forEach(d=>{const i=d.querySelector("textarea,input:not([type=checkbox])"),er=d.querySelector(".err");if(!i||!er)return;let m="";if(!i.value.trim())m="Required";else if(i.type=="email"&&!/^\S+@\S+\.\S+$/.test(i.value))m="Enter a valid email";er.textContent=m;if(m)ok=false});
if(f.id=="rq"){const sel=[...f.querySelectorAll("[name=rp]:checked")].map(x=>PROV.find(p=>p.id==x.value));const er=f.querySelectorAll(".err")[1];er.textContent=sel.length?(sel.length>3?"Choose at most 3":""):"Choose 1 to 3 providers";if(!sel.length||sel.length>3)ok=false;if(ok)$("#rr").innerHTML=`<h2>Replies (simulated)</h2><div class="g">${sel.map(p=>`<div class="c"><h3>${esc(p.name)}</h3>${avail(p)}<p class="m">Quote: waiting for reply (demo)</p></div>`).join("")}</div>`;return}
const o=f.querySelector(".ok");if(o)o.textContent=ok?"Looks valid. Demo only – nothing was sent.":""});
const lg=$("#lg");lg.value=LANG;lg.onchange=()=>{try{localStorage.setItem("lang",lg.value)}catch(e){}location.reload()};
try{if(localStorage.getItem("lite"))document.documentElement.classList.add("lite")}catch(e){}
$("#lt").onclick=()=>{const on=document.documentElement.classList.toggle("lite");try{localStorage.setItem("lite",on?"1":"")}catch(e){}};
if("serviceWorker" in navigator&&location.protocol.indexOf("http")==0)navigator.serviceWorker.register("sw.js").catch(()=>{});
updCmp();
route();